mapper.select:
select id, ledger_no, remittance_no, account_id, direction, currency, amount, balance_after,
       create_time, update_time
from cross_border_account_ledger
where account_id = #{accountId}
order by id desc
limit #{limit}

select ifnull(sum(amount), 0)
from cross_border_account_ledger
where account_id = #{accountId}
  and direction = #{direction}
